const clone = value => JSON.parse(JSON.stringify(value))
const merge = (base, extra) => {
  if (!extra || typeof extra !== 'object' || Array.isArray(extra)) return extra === undefined ? clone(base) : extra
  const output = clone(base)
  Object.entries(extra).forEach(([key, value]) => { output[key] = value && typeof value === 'object' && !Array.isArray(value) && output[key] && typeof output[key] === 'object' && !Array.isArray(output[key]) ? merge(output[key], value) : clone(value) })
  return output
}
const selectList = (current, value, checked) => checked ? [...new Set([...(current || []), value])] : (current || []).filter(item => item !== value)
const download = (content, filename, type) => { const url = URL.createObjectURL(new Blob([content], { type })); const link = document.createElement('a'); link.href = url; link.download = filename; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
const validationErrors = value => {
  const errors = []
  if (!String(value.name || '').trim()) errors.push('Informe um nome para o preset.')
  if (!value.architectures?.length) errors.push('Selecione pelo menos uma arquitetura.')
  if (value.computerName?.mode === 'fixed' && !/^[a-z0-9-]{1,15}$/i.test(value.computerName.value || '')) errors.push('O nome fixo do computador deve ter de 1 a 15 caracteres alfanuméricos ou hífen.')
  if (Number(value.disk?.minCapacityGiB) > Number(value.disk?.maxCapacityGiB)) errors.push('A capacidade mínima do disco não pode ser maior que a máxima.')
  if (value.paging?.mode === 'custom' && Number(value.paging.initialMiB) > Number(value.paging.maximumMiB)) errors.push('O tamanho inicial da paginação não pode ser maior que o máximo.')
  if (value.windowsPe?.imageIndex < 1) errors.push('O índice da imagem deve ser maior que zero.')
  if (value.download?.filename && !/\.xml$/i.test(value.download.filename)) errors.push('O nome do arquivo precisa terminar em .xml.')
  return errors
}

function Field({ label, children, hint }) { return <label className="form-field"><span>{label}</span>{children}{hint && <small className="field-hint">{hint}</small>}</label> }
function Check({ label, checked, onChange, hint }) { return <label className="check auto-option"><input type="checkbox" checked={Boolean(checked)} onChange={event => onChange(event.target.checked)} /><span>{label}{hint && <small>{hint}</small>}</span></label> }
function SelectList({ items, value = [], onChange }) { return <div className="auto-check-grid">{items.map(([id, label, hint]) => <Check key={id} label={label} hint={hint} checked={value.includes(id)} onChange={checked => onChange(selectList(value, id, checked))} />)}</div> }
function Section({ title, description, children, warning }) { return <details className="auto-section auto-details" open><summary><span><b>{title}</b>{description && <small>{description}</small>}</span><i>⌄</i></summary>{warning && <div className="auto-warning"><AlertTriangle size={16} />{warning}</div>}{children}</details> }

function normalizeSettings(settings) {
  const next = merge(defaultConfig, settings || {})
  if (typeof next.computerName === 'string') next.computerName = { mode: 'fixed', value: next.computerName, script: '' }
  return next
}

export function AutoAtendeWorkspace() {
  const [config, setConfig] = useState(clone(defaultConfig))
  const [presets, setPresets] = useState([])
  const [selected, setSelected] = useState(null)
  const [notice, setNotice] = useState('')
  const [error, setError] = useState('')
  const [showJson, setShowJson] = useState(false)
  const importInput = useRef(null)

  const update = (path, value) => setConfig(current => {
    const next = clone(current)
    const keys = path.split('.')
    let target = next
    keys.slice(0, -1).forEach(key => { target[key] = target[key] && typeof target[key] === 'object' ? target[key] : {}; target = target[key] })
    target[keys[keys.length - 1]] = value
    return next
  })
  const updateList = (path, id, checked) => update(path, selectList(path.split('.').reduce((item, key) => item?.[key], config) || [], id, checked))

  const load = async () => {
    try { const result = await api('/api/autounattend/presets'); setPresets(result); if (result[0]) applyPreset(result[0]); setError(''); setNotice('') }
    catch { const local = JSON.parse(localStorage.getItem('fixio_autounattend_presets') || '[]'); setPresets(local); if (local[0]) applyPreset(local[0]); setNotice(local.length ? 'Presets locais carregados.' : 'O backend não respondeu; os presets serão mantidos neste navegador.') }
  }
  useEffect(() => { load() }, [])

  const applyPreset = preset => {
    const settings = normalizeSettings(preset.settings || preset)
    const computerName = preset.computer_name || preset.computerName
    if (computerName && typeof computerName === 'string') settings.computerName = { ...settings.computerName, mode: 'fixed', value: computerName }
    setConfig(settings); setSelected(preset); setShowJson(false)
  }
  const reset = () => { setConfig(clone(defaultConfig)); setSelected(null); setNotice('Formulário restaurado para os valores padrão.'); setError('') }
  const payload = useMemo(() => ({ ...clone(config), format: 'fixio-autoatende/v2', schemaVersion: 2, generatedAt: new Date().toISOString() }), [config])
  const apiPayload = () => ({ name: config.name, computerName: config.computerName.mode === 'fixed' ? config.computerName.value : 'FIXIO-PC', enabledOptions: config.systemTweaks, appsToRemove: config.bloatware, settings: { ...clone(config), locale: config.language.display, keyboard: config.language.profiles[0]?.keyboard || config.keyboard, timezone: config.timezoneMode === 'explicit' ? config.timezone : '', edition: config.edition, oobe: { acceptEula: true, hideEula: true, hideOnlineAccount: true, hideWireless: true, protectYourPc: true, skipMachine: true, skipUser: true } } })

  const save = async event => {
    event.preventDefault()
    const errors = validationErrors(config)
    if (errors.length) { setError(errors.join(' ')); return }
    const body = apiPayload()
    try {
      const result = selected?.id ? await api(`/api/autounattend/presets/${selected.id}`, { method: 'PATCH', body: JSON.stringify(body) }) : await api('/api/autounattend/presets', { method: 'POST', body: JSON.stringify(body) })
      setPresets(current => selected?.id ? current.map(item => item.id === result.id ? result : item) : [...current, result]); applyPreset(result); setNotice('Preset completo salvo no backend.'); setError('')
    } catch {
      const local = { ...body, id: selected?.id || `local-${Date.now()}`, computer_name: body.computerName, enabled_options: body.enabledOptions, apps_to_remove: body.appsToRemove, settings: body.settings }
      const next = selected?.id ? presets.map(item => item.id === selected.id ? local : item) : [...presets, local]
      setPresets(next); localStorage.setItem('fixio_autounattend_presets', JSON.stringify(next)); setSelected(local); setNotice('Preset salvo localmente até o backend ficar disponível.'); setError('')
    }
  }
  const generateJson = () => { const errors = validationErrors(config); if (errors.length) { setError(errors.join(' ')); return }; download(JSON.stringify(payload, null, 2), `${config.name.replace(/[^a-z0-9]+/gi, '-').toLowerCase() || 'auto-atende'}.json`, 'application/json'); setNotice('JSON completo do Auto Atende baixado.'); setError('') }
  const generateXml = async () => {
    const errors = validationErrors(config)
    if (errors.length) { setError(errors.join(' ')); return }
    try { const result = await api('/api/autounattend/generate', { method: 'POST', body: JSON.stringify(apiPayload()) }); download(result.xml, config.download.filename || 'autounattend.xml', 'application/xml'); setNotice('autounattend.xml gerado. Revise-o antes de usar em uma mídia.') }
    catch (cause) { setError(cause.message); setNotice('O XML não foi gerado porque a API não respondeu.') }
  }
  const importJson = event => {
    const file = event.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => { try { const value = JSON.parse(String(reader.result)); setConfig(normalizeSettings(value)); setSelected(null); setNotice('JSON importado. Revise as opções e salve como um novo preset.'); setError('') } catch { setError('O arquivo selecionado não é um JSON válido do Auto Atende.') } }
    reader.readAsText(file); event.target.value = ''
  }

  return <>
    <section className="page-head auto-page-head"><div><p className="eyebrow">FERRAMENTAS</p><h1>Auto Atende</h1><p className="muted">Monte um preset completo para instalação autônoma. O JSON guarda todas as escolhas; o XML é o arquivo lido pelo Windows Setup.</p></div><div className="auto-head-actions"><button className="outline" type="button" onClick={() => importInput.current?.click()}><Upload size={16} />Importar JSON</button><input ref={importInput} type="file" accept="application/json,.json" hidden onChange={importJson} /><button className="outline" type="button" onClick={reset}><RotateCcw size={16} />Restaurar</button></div></section>
    {notice && <div className="auto-notice"><CheckCircle2 size={17} />{notice}</div>}
    {error && <div className="api-error"><AlertTriangle size={18} />{error}</div>}
    <form className="auto-layout auto-full-layout" onSubmit={save}>
      <div className="panel auto-editor">
        <Section title="Identidade do sistema" description="Dados registrados no Windows instalado."><div className="form-grid"><Field label="Organização"><input value={config.organization} onChange={e => update('organization', e.target.value)} /></Field><Field label="Usuário registrado"><input value={config.owner} onChange={e => update('owner', e.target.value)} /></Field><Field label="Conta local padrão"><input value={config.localUserName} onChange={e => update('localUserName', e.target.value)} /></Field></div></Section>
        <div className="panel-head auto-sticky-head"><div><h2>Configuração completa</h2><p>{selected ? `Editando: ${selected.name}` : 'Escolha somente o que precisa; campos não usados permanecem neutros.'}</p></div><button className="primary" type="submit"><Save size={16} />Salvar preset</button></div>
        <Section title="Identificação e idioma" description="Região, idioma de exibição e layouts de teclado."><div className="form-grid"><Field label="Nome do preset"><input value={config.name} onChange={e => update('name', e.target.value)} required /></Field><Field label="Idioma de exibição"><select value={config.language.display} onChange={e => { update('language.display', e.target.value); update('locale', e.target.value) }}>{languages.map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></Field><Field label="Região inicial"><select value={config.language.homeRegion} onChange={e => update('language.homeRegion', e.target.value)}>{regions.map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></Field><Field label="Edição padrão"><select value={config.edition} onChange={e => update('edition', e.target.value)}>{editions.map(value => <option key={value}>{value}</option>)}</select></Field></div><div className="auto-subtitle">Preferência de idiomas e teclados</div><div className="form-grid">{config.language.profiles.map((profile, index) => <div className="auto-language-row" key={index}><b>{index + 1}º idioma</b><select value={profile.language} onChange={e => { const next = clone(config.language.profiles); next[index].language = e.target.value; update('language.profiles', next) }}><option value="">Não especificado</option>{languages.map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select><select value={profile.keyboard} onChange={e => { const next = clone(config.language.profiles); next[index].keyboard = e.target.value; update('language.profiles', next) }}><option value="">Layout padrão</option>{keyboards.map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></div>)}</div><Check label="Selecionar configurações de idioma interativamente no Setup" checked={config.language.interactive} onChange={value => update('language.interactive', value)} /></Section>
        <Section title="Windows PE e imagem" description="Como o Setup escolhe a edição, a imagem e as ações no ambiente PE."><div className="form-grid"><Field label="Etapa Windows PE"><select value={config.windowsPe.interactive ? 'interactive' : 'automatic'} onChange={e => update('windowsPe.interactive', e.target.value === 'interactive')}><option value="automatic">Automática</option><option value="interactive">Interativa</option></select></Field><Field label="Modo de chave da edição"><select value={config.windowsPe.editionMode} onChange={e => update('windowsPe.editionMode', e.target.value)}><option value="generic">Chave genérica</option><option value="custom">Outra chave</option><option value="firmware">Chave no BIOS/UEFI</option><option value="interactive">Perguntar no Setup</option></select></Field><Field label="Edição da imagem"><select value={config.windowsPe.imageName} onChange={e => update('windowsPe.imageName', e.target.value)}>{editions.map(value => <option key={value}>Windows 11 {value}</option>)}</select></Field><Field label="Índice da imagem"><input type="number" min="1" value={config.windowsPe.imageIndex} onChange={e => update('windowsPe.imageIndex', Number(e.target.value) || 1)} /></Field><Field label="Chave do produto"><input value={config.windowsPe.productKey} onChange={e => update('windowsPe.productKey', e.target.value)} placeholder="XXXXX-XXXXX-XXXXX-XXXXX-XXXXX" /></Field><Field label="Nome da imagem (WIM/ESD)"><input value={config.windowsPe.imageName} onChange={e => update('windowsPe.imageName', e.target.value)} /></Field></div><div className="auto-check-grid">{[['generateScript', 'Gerar script .cmd para a etapa PE'], ['disable83', 'Desabilitar nomes de arquivo 8.3'], ['disableDefender', 'Desabilitar Windows Defender durante o PE'], ['pauseBeforePartition', 'Pausar antes de particionar e formatar'], ['pauseBeforeReboot', 'Pausar antes do reinício do PE'], ['compactImage', 'Aplicar imagem em modo compacto'], ['skipIntegrity', 'Ignorar verificação de integridade'], ['imageInteractive', 'Selecionar a imagem interativamente']].map(([id, label]) => <Check key={id} label={label} checked={config.windowsPe[id]} onChange={value => update(`windowsPe.${id}`, value)} />)}</div></Section>
        <Section title="Particionamento e formatação" description="Critérios do disco, layout e Windows RE." warning="Opções de limpeza de disco são destrutivas. O JSON apenas registra a escolha; revise o destino em uma VM antes de usar."><div className="form-grid"><Field label="Modo de seleção do disco"><select value={config.disk.targetMode} onChange={e => update('disk.targetMode', e.target.value)}><option value="criteria">Critérios de segurança</option><option value="interactive">Perguntar no Setup</option><option value="vbs">Script VBS próprio</option></select></Field><Field label="Layout"><select value={config.disk.layout} onChange={e => update('disk.layout', e.target.value)}><option value="automatic">Automático (BIOS/UEFI)</option><option value="gpt">GPT / UEFI</option><option value="mbr">MBR / BIOS</option></select></Field><Field label="Controlador"><select value={config.disk.controller} onChange={e => update('disk.controller', e.target.value)}><option value="any">Qualquer</option><option value="sata-scsi-sas-nvme">SATA, SCSI, SAS ou NVMe</option></select></Field><Field label="Tipo de mídia"><select value={config.disk.mediaType} onChange={e => update('disk.mediaType', e.target.value)}><option value="fixed">Disco fixo</option><option value="any">Qualquer mídia</option></select></Field><Field label="Capacidade mínima (GiB)"><input type="number" min="0" value={config.disk.minCapacityGiB} onChange={e => update('disk.minCapacityGiB', Number(e.target.value) || 0)} /></Field><Field label="Capacidade máxima (GiB)"><input type="number" min="0" value={config.disk.maxCapacityGiB} onChange={e => update('disk.maxCapacityGiB', Number(e.target.value) || 0)} /></Field><Field label="Índice do disco (0-based)"><input type="number" min="0" value={config.disk.index} onChange={e => update('disk.index', Number(e.target.value) || 0)} /></Field><Field label="Partição do sistema (MiB)"><input type="number" min="100" value={config.disk.systemPartitionMiB} onChange={e => update('disk.systemPartitionMiB', Number(e.target.value) || 300)} /></Field><Field label="Windows RE"><select value={config.disk.recoveryMode} onChange={e => update('disk.recoveryMode', e.target.value)}><option value="partition">Partição de recuperação</option><option value="remove">Remover Windows RE</option><option value="custom">Script personalizado</option></select></Field><Field label="Partição de recuperação (MiB)"><input type="number" min="0" value={config.disk.recoverySizeMiB} onChange={e => update('disk.recoverySizeMiB', Number(e.target.value) || 0)} /></Field></div><Check label="Exigir que o disco não tenha partições existentes" checked={config.disk.requireNoPartitions} onChange={value => update('disk.requireNoPartitions', value)} /><Field label="Script VBS para localizar o disco"><textarea rows="7" value={config.disk.vbsScript} onChange={e => update('disk.vbsScript', e.target.value)} placeholder="O script deve escrever o índice do disco com WScript.Echo e sair com código 1 em caso de erro." /></Field><Field label="Script DiskPart personalizado"><textarea rows="7" value={config.disk.diskpartScript} onChange={e => update('disk.diskpartScript', e.target.value)} placeholder={'SELECT DISK=0\nCLEAN\nCONVERT GPT'} /></Field></Section>
        <Section title="Arquivo de paginação e scripts do PE" description="Memória virtual e script completo opcional."><div className="form-grid"><Field label="Arquivo de paginação"><select value={config.paging.mode} onChange={e => update('paging.mode', e.target.value)}><option value="managed">Gerenciado pelo Windows</option><option value="custom">Tamanho personalizado</option><option value="none">Sem arquivo de paginação</option></select></Field><Field label="Tamanho inicial (MiB)"><input type="number" min="0" value={config.paging.initialMiB} onChange={e => update('paging.initialMiB', Number(e.target.value) || 0)} /></Field><Field label="Tamanho máximo (MiB)"><input type="number" min="0" value={config.paging.maximumMiB} onChange={e => update('paging.maximumMiB', Number(e.target.value) || 0)} /></Field></div><Field label="Script .cmd de toda a etapa Windows PE"><textarea rows="12" value={config.windowsPe.customScript} onChange={e => update('windowsPe.customScript', e.target.value)} placeholder="O PowerShell normalmente não está disponível no Windows PE." /></Field></Section>
        <Section title="Ativação, arquiteturas e Setup" description="Chave, compatibilidade e comportamento do instalador."><div className="form-grid"><Field label="Chave para ativação"><input value={config.activation.productKey} onChange={e => update('activation.productKey', e.target.value)} placeholder="XXXXX-XXXXX-XXXXX-XXXXX-XXXXX" /></Field><Field label="Nome do computador"><select value={config.computerName.mode} onChange={e => update('computerName.mode', e.target.value)}><option value="random">Gerar aleatoriamente</option><option value="fixed">Escolher nome</option><option value="script">Script PowerShell</option></select></Field>{config.computerName.mode === 'fixed' ? <Field label="Nome fixo"><input maxLength="15" value={config.computerName.value} onChange={e => update('computerName.value', e.target.value)} /></Field> : <Field label="Script do nome"><textarea rows="2" value={config.computerName.script} onChange={e => update('computerName.script', e.target.value)} placeholder="return 'DESKTOP-{0:D3}' -f (Get-Random -Minimum 0 -Maximum 999);" /></Field>}<Field label="Fuso horário"><select value={config.timezoneMode} onChange={e => update('timezoneMode', e.target.value)}><option value="auto">Detectar pela região</option><option value="explicit">Definir explicitamente</option></select></Field>{config.timezoneMode === 'explicit' && <Field label="Fuso horário explícito"><input value={config.timezone} onChange={e => update('timezone', e.target.value)} /></Field>}</div><div className="auto-subtitle">Arquiteturas aplicáveis</div><SelectList items={architectures} value={config.architectures} onChange={value => update('architectures', value)} /><div className="auto-subtitle">Configurações do Setup</div><div className="auto-check-grid">{[['bypassRequirements', 'Registrar opção de compatibilidade para requisitos do Windows 11'], ['allowOffline', 'Permitir instalação sem internet'], ['distributionShare', 'Usar distribuição / configuração $OEM$'], ['hidePowerShell', 'Ocultar janelas PowerShell durante o Setup'], ['keepSensitiveFiles', 'Manter arquivos sensíveis após o Setup'], ['narrator', 'Iniciar Narrator durante o Setup e após o logon']].map(([id, label]) => <Check key={id} label={label} checked={config.setup[id]} onChange={value => update(`setup.${id}`, value)} />)}</div></Section>
        <Section title="Contas, logon e segurança" description="Contas locais, expiração e bloqueio. Senhas ficam no preset somente se você escolher exportá-las."><div className="auto-subtitle">Contas locais</div>{config.accounts.local.map((account, index) => <div className="auto-account-row" key={index}><input placeholder="Conta" value={account.name} onChange={e => { const next = clone(config.accounts.local); next[index].name = e.target.value; update('accounts.local', next) }} /><input placeholder="Nome exibido" value={account.displayName} onChange={e => { const next = clone(config.accounts.local); next[index].displayName = e.target.value; update('accounts.local', next) }} /><input type="password" placeholder="Senha opcional" value={account.password} onChange={e => { const next = clone(config.accounts.local); next[index].password = e.target.value; update('accounts.local', next) }} /><select value={account.group} onChange={e => { const next = clone(config.accounts.local); next[index].group = e.target.value; update('accounts.local', next) }}><option>Administrators</option><option>Users</option><option>Guests</option></select><button type="button" className="icon-button" onClick={() => update('accounts.local', config.accounts.local.filter((_, itemIndex) => itemIndex !== index))}><Trash2 size={15} /></button></div>)}<button type="button" className="outline auto-add-button" onClick={() => update('accounts.local', [...config.accounts.local, { name: '', displayName: '', password: '', group: 'Users' }])}><Plus size={15} />Adicionar conta local</button><div className="form-grid"><Field label="Primeiro logon"><select value={config.accounts.firstLogon} onChange={e => update('accounts.firstLogon', e.target.value)}><option value="first-admin">Primeira conta administradora</option><option value="built-in">Ativar Administrator e definir senha</option><option value="none">Não fazer logon</option></select></Field><Field label="Senha do Administrator"><input type="password" value={config.accounts.builtInPassword} onChange={e => update('accounts.builtInPassword', e.target.value)} /></Field><Field label="Expiração de senha"><select value={config.password.expiration} onChange={e => update('password.expiration', e.target.value)}><option value="never">Nunca expira</option><option value="default">Padrão do Windows</option><option value="custom">Personalizada</option></select></Field><Field label="Dias para expiração"><input type="number" min="1" value={config.password.customDays} onChange={e => update('password.customDays', Number(e.target.value) || 1)} /></Field><Field label="Política de bloqueio"><select value={config.password.lockout} onChange={e => update('password.lockout', e.target.value)}><option value="default">Padrão</option><option value="disabled">Desabilitada</option><option value="custom">Personalizada</option></select></Field><Field label="Tentativas até bloquear"><input type="number" min="0" value={config.password.threshold} onChange={e => update('password.threshold', Number(e.target.value) || 0)} /></Field></div><Check label="Ofuscar senhas no JSON/XML com Base64" checked={config.accounts.obscurePasswords} onChange={value => update('accounts.obscurePasswords', value)} /><Check label="Adicionar conta Microsoft interativamente" checked={config.accounts.interactiveOnline} onChange={value => update('accounts.interactiveOnline', value)} /><Check label="Adicionar conta local interativamente" checked={config.accounts.interactiveLocal} onChange={value => update('accounts.interactiveLocal', value)} /></Section>
        <Section title="Explorador, barra de tarefas e menu Iniciar" description="Ajustes de interface reproduzidos como dados no JSON."><div className="form-grid"><Field label="Arquivos ocultos"><select value={config.explorer.hiddenFiles} onChange={e => update('explorer.hiddenFiles', e.target.value)}><option value="default">Padrão</option><option value="protected">Ocultar arquivos protegidos</option><option value="all">Mostrar todos</option></select></Field><Field label="Busca na barra de tarefas"><select value={config.taskbar.search} onChange={e => update('taskbar.search', e.target.value)}><option value="full">Completa</option><option value="icon-label">Ícone e rótulo</option><option value="icon">Ícone</option><option value="hide">Oculta</option></select></Field><Field label="Ícones da barra"><select value={config.taskbar.icons} onChange={e => update('taskbar.icons', e.target.value)}><option value="default">Padrão</option><option value="none">Remover todos</option><option value="xml">XML personalizado</option></select></Field><Field label="Tiles do Windows 10"><select value={config.startMenu.tiles} onChange={e => update('startMenu.tiles', e.target.value)}><option value="default">Padrão</option><option value="none">Remover todos</option><option value="xml">XML personalizado</option></select></Field><Field label="Pins do Windows 11"><select value={config.startMenu.pins} onChange={e => update('startMenu.pins', e.target.value)}><option value="default">Padrão</option><option value="none">Remover todos</option><option value="json">JSON personalizado</option></select></Field></div><div className="auto-check-grid">{[['showExtensions', 'Sempre mostrar extensões'], ['classicContextMenu', 'Usar menu de contexto clássico'], ['hideDescriptions', 'Ocultar descrição de pastas e itens'], ['openThisPc', 'Abrir Este Computador em vez do Acesso rápido'], ['showEndTask', 'Mostrar comando Finalizar tarefa'], ['disableWidgets', 'Desabilitar widgets'], ['alignLeft', 'Alinhar barra à esquerda'], ['hideTaskView', 'Ocultar botão Task View'], ['showAllTrayIcons', 'Mostrar todos os ícones da bandeja'], ['hideBing', 'Não mostrar resultados Bing']].map(([id, label]) => <Check key={id} label={label} checked={config.explorer[id] ?? config.taskbar[id]} onChange={value => update(id in config.explorer ? `explorer.${id}` : `taskbar.${id}`, value)} />)}</div><Field label="XML de layout da barra de tarefas"><textarea rows="5" value={config.taskbar.customXml} onChange={e => update('taskbar.customXml', e.target.value)} /></Field><Field label="JSON de pins do menu Iniciar"><textarea rows="5" value={config.startMenu.pinsJson} onChange={e => update('startMenu.pinsJson', e.target.value)} /></Field></Section>
        <Section title="Ajustes do sistema" description="Políticas avançadas, privacidade e desempenho." warning="Alguns ajustes reduzem proteções do Windows. Use em VM/laboratório e mantenha uma cópia do JSON original."><SelectList items={systemTweaks.map(([id, label, hint]) => [id, label, hint])} value={config.systemTweaks} onChange={value => update('systemTweaks', value)} /></Section>
        <Section title="Efeitos visuais, ícones e pastas" description="Preferências de aparência, Desktop e menu Iniciar."><div className="form-grid"><Field label="Efeitos visuais"><select value={config.visualEffects.mode} onChange={e => update('visualEffects.mode', e.target.value)}><option value="default">Padrão do Windows</option><option value="appearance">Melhor aparência</option><option value="performance">Melhor desempenho</option><option value="custom">Personalizado</option></select></Field><Field label="Ícones da área de trabalho"><select value={config.desktop.iconsMode} onChange={e => update('desktop.iconsMode', e.target.value)}><option value="default">Padrão</option><option value="custom">Personalizados</option></select></Field><Field label="Pastas no menu Iniciar"><select value={config.desktop.startFoldersMode} onChange={e => update('desktop.startFoldersMode', e.target.value)}><option value="default">Padrão</option><option value="custom">Personalizadas</option></select></Field></div><Check label="Excluir atalho do Edge na área de trabalho" checked={config.desktop.deleteEdgeShortcut} onChange={value => update('desktop.deleteEdgeShortcut', value)} /><div className="auto-subtitle">Ícones visíveis</div><SelectList items={desktopIconOptions} value={config.desktop.icons} onChange={value => update('desktop.icons', value)} /><div className="auto-subtitle">Pastas visíveis no menu Iniciar</div><SelectList items={startFolderOptions} value={config.desktop.startFolders} onChange={value => update('desktop.startFolders', value)} /><div className="auto-subtitle">Efeitos personalizados</div><SelectList items={visualEffectOptions} value={config.visualEffects.custom} onChange={value => update('visualEffects.custom', value)} /></Section>
        <Section title="Máquinas virtuais e Wi‑Fi" description="Integração com hosts/convidados e rede durante o Setup."><div className="form-grid"><Field label="Isolamento do núcleo"><select value={config.virtualization.coreIsolation} onChange={e => update('virtualization.coreIsolation', e.target.value)}><option value="keep">Manter se compatível</option><option value="disable">Desabilitar</option></select></Field><Field label="Configuração de Wi‑Fi"><select value={config.wifi.mode} onChange={e => update('wifi.mode', e.target.value)}><option value="interactive">Interativa</option><option value="skip">Pular configuração</option><option value="settings">Usar configurações abaixo</option><option value="xml">Importar XML de perfil</option></select></Field><Field label="SSID"><input value={config.wifi.ssid} onChange={e => update('wifi.ssid', e.target.value)} /></Field><Field label="Autenticação"><select value={config.wifi.authentication} onChange={e => update('wifi.authentication', e.target.value)}><option value="open">Open</option><option value="WPA2PSK">WPA2-PSK</option><option value="WPA3SAE">WPA3-SAE</option></select></Field><Field label="Senha Wi‑Fi"><input type="password" value={config.wifi.password} onChange={e => update('wifi.password', e.target.value)} /></Field></div><Check label="Conectar mesmo sem transmitir o SSID" checked={config.wifi.hidden} onChange={value => update('wifi.hidden', value)} /><div className="auto-subtitle">Convidados</div><SelectList items={vmGuests} value={config.virtualization.guests} onChange={value => update('virtualization.guests', value)} /><Field label="XML de perfil Wi‑Fi"><textarea rows="6" value={config.wifi.profileXml} onChange={e => update('wifi.profileXml', e.target.value)} /></Field></Section>
        <Section title="Express settings, teclas e acessibilidade" description="Privacidade inicial, estados de Lock keys e Sticky Keys."><div className="form-grid"><Field label="Express settings"><select value={config.expressSettings} onChange={e => update('expressSettings', e.target.value)}><option value="disable-all">Desabilitar tudo</option><option value="enable-all">Habilitar tudo</option><option value="interactive">Interativo</option></select></Field><Field label="Lock keys"><select value={config.lockKeys.mode} onChange={e => update('lockKeys.mode', e.target.value)}><option value="default">Padrão</option><option value="custom">Personalizado</option></select></Field><Field label="Caps Lock"><select value={config.lockKeys.caps} onChange={e => update('lockKeys.caps', e.target.value)}><option value="off">Desligado</option><option value="on">Ligado</option><option value="toggle">Alternar</option></select></Field><Field label="Num Lock"><select value={config.lockKeys.num} onChange={e => update('lockKeys.num', e.target.value)}><option value="off">Desligado</option><option value="on">Ligado</option><option value="toggle">Alternar</option></select></Field><Field label="Sticky Keys"><select value={config.stickyKeys.mode} onChange={e => update('stickyKeys.mode', e.target.value)}><option value="default">Padrão</option><option value="disabled">Desabilitar completamente</option><option value="custom">Personalizado</option></select></Field></div><Check label="Scroll Lock ligado" checked={config.lockKeys.scroll === 'on'} onChange={value => update('lockKeys.scroll', value ? 'on' : 'off')} /><div className="auto-check-grid">{[['shiftToggle', 'Atalho Shift 5 vezes liga/desliga Sticky Keys'], ['siren', 'Tocar sirene ao alternar'], ['taskbarIcon', 'Mostrar ícone na barra'], ['shortcutSound', 'Tocar som nos atalhos'], ['lockShortcuts', 'Travar atalhos ao pressionar duas vezes'], ['turnOffWithTwoKeys', 'Desligar ao pressionar duas teclas']].map(([id, label]) => <Check key={id} label={label} checked={config.stickyKeys[id]} onChange={value => update(`stickyKeys.${id}`, value)} />)}</div></Section>
        <Section title="Personalização" description="Cores, papel de parede e tela de bloqueio."><div className="form-grid"><Field label="Tema de cores"><select value={config.personalization.colorsMode} onChange={e => update('personalization.colorsMode', e.target.value)}><option value="default">Padrão</option><option value="custom">Personalizado</option></select></Field><Field label="Tema da barra e Iniciar"><select value={config.personalization.taskbarTheme} onChange={e => update('personalization.taskbarTheme', e.target.value)}><option value="light">Claro</option><option value="dark">Escuro</option></select></Field><Field label="Tema dos aplicativos"><select value={config.personalization.appTheme} onChange={e => update('personalization.appTheme', e.target.value)}><option value="light">Claro</option><option value="dark">Escuro</option></select></Field><Field label="Cor de destaque"><input type="color" value={config.personalization.accentColor || '#2c9c87'} onChange={e => update('personalization.accentColor', e.target.value)} /></Field><Field label="Papel de parede"><select value={config.personalization.wallpaperMode} onChange={e => update('personalization.wallpaperMode', e.target.value)}><option value="default">Padrão</option><option value="solid">Cor sólida</option><option value="script">Script PowerShell</option></select></Field><Field label="Tela de bloqueio"><select value={config.personalization.lockScreenMode} onChange={e => update('personalization.lockScreenMode', e.target.value)}><option value="default">Padrão</option><option value="script">Script PowerShell</option></select></Field></div><div className="form-grid"><Check label="Mostrar destaque no menu Iniciar e barra" checked={config.personalization.accentOnStart} onChange={value => update('personalization.accentOnStart', value)} /><Check label="Mostrar destaque nas bordas" checked={config.personalization.accentOnTitleBars} onChange={value => update('personalization.accentOnTitleBars', value)} /><Check label="Superfícies translúcidas" checked={config.personalization.translucent} onChange={value => update('personalization.translucent', value)} /></div><Field label="Script do papel de parede"><textarea rows="5" value={config.personalization.wallpaperScript} onChange={e => update('personalization.wallpaperScript', e.target.value)} /></Field><Field label="Script da tela de bloqueio"><textarea rows="5" value={config.personalization.lockScreenScript} onChange={e => update('personalization.lockScreenScript', e.target.value)} /></Field></Section>
        <Section title="Remover bloatware" description="Selecione os pacotes que devem ser removidos durante o Setup." warning="A reinstalação de alguns componentes, especialmente Microsoft Store, pode ser difícil. Gere uma cópia do JSON antes."><SelectList items={bloatware} value={config.bloatware} onChange={value => update('bloatware', value)} /></Section>
        <Section title="Scripts personalizados" description="Scripts de sistema, usuário padrão, primeiro logon e UserOnce."><div className="script-grid">{[['system', 'System scripts'], ['defaultUser', 'DefaultUser scripts'], ['firstLogon', 'FirstLogon scripts'], ['userOnce', 'UserOnce scripts']].map(([id, label]) => <article className="auto-script-card" key={id}><h4>{label}</h4>{[['cmd', '.cmd'], ['ps1', '.ps1'], ['reg', '.reg'], ['vbs', '.vbs']].map(([type, text]) => <Field key={type} label={text}><textarea rows="3" value={config.scripts[id][type]} onChange={e => update(`scripts.${id}.${type}`, e.target.value)} /></Field>)}</article>)}</div><Check label="Reiniciar o Explorer depois dos scripts" checked={config.scripts.restartExplorer} onChange={value => update('scripts.restartExplorer', value)} /></Section>
        <Section title="AppLocker e XML adicional" description="Política completa e componentes não cobertos pelos campos acima."><Field label="AppLocker"><select value={config.appLocker.mode} onChange={e => update('appLocker.mode', e.target.value)}><option value="none">Não configurar</option><option value="custom">Aplicar política XML</option></select></Field><Field label="Política AppLocker XML"><textarea rows="10" value={config.appLocker.policyXml} onChange={e => update('appLocker.policyXml', e.target.value)} /></Field>{config.xmlComponents.map((item, index) => <div className="auto-xml-row" key={index}><input placeholder="Componente (ex.: Microsoft-Windows-Shell-Setup)" value={item.component} onChange={e => { const next = clone(config.xmlComponents); next[index].component = e.target.value; update('xmlComponents', next) }} /><textarea rows="3" placeholder="Markup XML sem <settings> ou <component>" value={item.markup} onChange={e => { const next = clone(config.xmlComponents); next[index].markup = e.target.value; update('xmlComponents', next) }} /></div>)}</Section>
        <Section title="Download e saída" description="Defina os nomes e formatos do arquivo final."><div className="form-grid"><Field label="Nome do XML"><input value={config.download.filename} onChange={e => update('download.filename', e.target.value)} /></Field><Check label="Gerar XML dentro de ISO" checked={config.download.wrappedIso} onChange={value => update('download.wrappedIso', value)} /></div><Field label="Comando PowerShell adicional"><textarea rows="4" value={config.customCommand} onChange={e => update('customCommand', e.target.value)} placeholder="Opcional. Será incluído no preset enviado à API." /></Field></Section>
        <div className="auto-bottom-actions"><button className="outline" type="button" onClick={() => setShowJson(value => !value)}><FileJson size={16} />{showJson ? 'Ocultar JSON' : 'Visualizar JSON'}</button><button className="outline" type="button" onClick={generateJson}><Download size={16} />Baixar JSON completo</button><button className="primary" type="button" onClick={generateXml}><FileCode2 size={16} />Gerar autounattend.xml</button></div>{showJson && <pre className="auto-json-preview">{JSON.stringify(payload, null, 2)}</pre>}
      </div>
      <aside className="auto-side"><article className="panel"><div className="panel-head"><div><h2>Presets salvos</h2><p>{presets.length} configuração(ões)</p></div></div>{presets.length ? presets.map(item => <button className={selected?.id === item.id ? 'auto-preset active' : 'auto-preset'} key={item.id} type="button" onClick={() => applyPreset(item)}><span><b>{item.name}</b><small>{item.computer_name || item.computerName || 'Sem nome'} · {item.settings?.language?.display || item.settings?.locale || 'pt-BR'}</small></span><span>›</span></button>) : <div className="empty-state">Nenhum preset salvo.</div>}</article><article className="panel auto-summary"><h2>Saída do formulário</h2><code>auto-atende-preset.json</code><span><CheckCircle2 size={15} />JSON versionado com todas as seções</span><span><CheckCircle2 size={15} />Importação de preset disponível</span><span><CheckCircle2 size={15} />XML separado para o Windows Setup</span><span><CheckCircle2 size={15} />Sem gravação ou formatação automática de disco</span><button className="outline" type="button" onClick={generateJson}><Download size={15} />Exportar preset JSON</button></article></aside>
    </form>
  </>
}
